const sales = parseCsv(readFileSync(salesPath, 'utf8'));
const totals = new Map();
for (const row of sales) totals.set(row.month, (totals.get(row.month) ?? 0) + row.amount);

const rows = [...totals.entries()].sort(([a], [b]) => a.localeCompare(b));
let previous = null;
const outputRows = [['month', 'total_sales', 'mom_growth_rate']];
for (const [month, total] of rows) {
  const mom = previous === null ? null : (total - previous) / previous;
  outputRows.push([month, formatMoney(total), formatMom(mom)]);
  previous = total;
}

